def decode_repetitions(text):
    def parse(index, active):
        parts = []
        while index < len(text):
            char = text[index]
            if char.isdigit():
                count = 0
                while text[index].isdigit():
                    count = count * 10 + int(text[index])
                    index += 1
                chunk, index = parse(index + 1, active and count > 0)
                if active:
                    parts.append(chunk * count)
            elif char == ']':
                return ''.join(parts), index + 1
            else:
                if active:
                    parts.append(char)
                index += 1
        return ''.join(parts), index
    return parse(0, True)[0]

