from collections import OrderedDict

def lru_gets(capacity, operations):
    cache = OrderedDict()
    results = []
    for op in operations:
        if op[0] == 'put':
            key, value = op[1], op[2]
            if key in cache:
                cache[key] = value
                cache.move_to_end(key)
            else:
                cache[key] = value
                if len(cache) > capacity:
                    cache.popitem(last=False)
        else:
            key = op[1]
            if key in cache:
                cache.move_to_end(key)
                results.append(cache[key])
            else:
                results.append(-1)
    return results

