        if op[0] == 'put':
            key, value = op[1], op[2]
            if key in cache:
                cache[key] = value
                touch(key)
            else:
                cache[key] = value
                order.append(key)
                if len(order) > capacity:
                    old = order.pop(0)
                    del cache[old]
        else:
            key = op[1]
            if key in cache:
                touch(key)
                results.append(cache[key])
            else:
                results.append(-1)
    return results

